function renderVoidCardManagement(){var cards=getVoidCardListData();var cols=['报告卡编号','姓名','身份证号码','性别','年龄','出生日期','发病部位','ICD10','确诊日期','最后接触状态','最后接触时间','报告单位','来源类型','上传日期','报告卡类型'];var rows=cards.map(function(card){var age=card.birth?Math.floor((new Date()-new Date(card.birth))/(365.25*24*3600*1000)):'-';var follow=(window.reportCardFollowup||{})[card.id]||{};var source=sourceDataRecords.find(function(record){return record.linkedCards.includes(card.id)});return '<tr><td><a href="javascript:void(0)" style="color:var(--primary)" onclick="cardListDetail(\''+card.id+'\')">'+card.id+'</a></td><td>'+card.name+'</td><td>'+card.idNo+'</td><td>'+card.sex+'</td><td>'+age+'</td><td>'+card.birth+'</td><td>'+card.site+'</td><td>'+(card.icd10||'-')+'</td><td>'+card.diagnosisDate+'</td><td>'+(follow.state||'-')+'</td><td>'+(follow.dlc||'-')+'</td><td>'+card.reportUnit+'</td><td>'+(source?source.sourceType:'手工登记')+'</td><td>'+(source?source.uploadTime.slice(0,10):'-')+'</td><td>'+card.auditStatus+'</td><td class="sticky-col"><button class="btn btn-danger btn-xs" onclick="deleteVoidCard(\''+card.id+'\')">删除</button> <button class="btn btn-primary btn-xs" onclick="restoreVoidCard(\''+card.id+'\')">恢复</button></td></tr>'}).join('');return '<div class="page-toolbar"><div class="toolbar-actions"><button class="btn btn-primary btn-sm" onclick="cardListAdd()">+ 添加</button><button class="btn btn-import btn-sm" onclick="navigateTo(\'collection-batch\');setTimeout(function(){openBatchImportDialog()},100)">批量添加</button><button class="btn btn-outline btn-sm" onclick="toast(\'导出Excel中...\')">导出Excel</button></div></div><div class="panel"><div class="panel-body"><div class="filter-toolbar"><div class="form-group region-filter" style="min-width:200px"><label>行政区划</label>'+renderRegionCascader()+'</div><div class="form-group"><label>报告卡类型</label><select><option value="">全部</option><option>原始卡</option><option>补报卡</option><option>合并卡</option><option>克隆卡</option><option>多原发卡</option></select></div><div class="form-group"><label>校验状态</label><select><option value="">全部</option><option>已关联</option><option>未关联</option></select></div><div class="form-group"><label>日期类型</label><select><option>报告日期</option><option>登记日期</option><option>确诊日期</option></select></div><div class="form-group date-group"><label>日期区间</label>'+renderDateRangePicker('dr_void','','')+'</div><div class="form-group search-group"><label>检索内容</label><input type="text" placeholder="报告卡编号 / 姓名 / 身份证号"></div><div class="filter-actions"><button class="btn btn-ghost btn-sm" onclick="renderPage(\'collection-death\')">重置</button></div></div><div style="margin-bottom:8px;color:#667085;font-size:13px">共 '+cards.length+' 张报告卡</div><div style="border:1px solid #e2e8f0;border-radius:6px;overflow:hidden;margin-bottom:12px"><div class="table-wrap"><table class="data-table" style="margin:0;min-width:1900px"><thead><tr>'+cols.map(function(col){return '<th>'+col+'</th>'}).join('')+'<th class="sticky-col">操作</th></tr></thead><tbody>'+(rows||'<tr><td colspan="16" style="text-align:center;padding:36px;color:#98a2b3">暂无作废报告卡</td></tr>')+'</tbody></table></div></div><div class="void-pagination"><div class="void-pagination-info">共'+cards.length+'条记录，第1/1页</div><div class="void-pagination-controls"><button onclick="toast(\'已是第一页\')">‹</button><input type="text" value="1" readonly><button onclick="toast(\'已是最后一页\')">›</button></div></div></div></div>'}

