function openSourceDataDetail(id){reportDataState.view='source-detail';reportDataState.selectedSourceId=id;reportDataState.editing=false;renderPage('datamgmt-source');setActiveMenu('datamgmt-source');updateBreadcrumb('datamgmt-source','上报数据详情');window.scrollTo(0,0)}
function startSourceRevision(id){reportDataState.view='source-detail';reportDataState.selectedSourceId=id;reportDataState.editing=true;renderPage('datamgmt-source');setActiveMenu('datamgmt-source');updateBreadcrumb('datamgmt-source','修订上报数据');window.scrollTo(0,0)}

function renderSourceDataDetail(){
var record=sourceDataRecords.find(function(item){return item.id===reportDataState.selectedSourceId});if(!record)return '<div class="empty-state">未找到源数据</div>';
var detailCard=(window.reportCardListData||[]).find(function(item){return item.idNo===record.idNo||record.linkedCards.includes(item.id)})||{};
var fields=[['发病部位','site'],['病理类型','pathology'],['ICD10','icd10']];
var compareRows=fields.map(function(field){var changed=record.original[field[1]]!==record.current[field[1]];return '<tr><td>'+field[0]+'</td><td>'+record.original[field[1]]+'</td><td class="'+(changed?'source-change':'')+'">'+record.current[field[1]]+'</td><td>'+(changed?'已修订':'未修改')+'</td></tr>'}).join('');
var revisionForm=reportDataState.editing?'<div class="source-section"><div class="source-section-title">新建修订版本</div><div class="source-revision-form"><div><label>发病部位</label><input id="sourceEditSite" value="'+record.current.site+'"></div><div><label>病理类型</label><input id="sourceEditPathology" value="'+record.current.pathology+'"></div><div><label>ICD10</label><input id="sourceEditIcd10" value="'+record.current.icd10+'"></div><div class="source-revision-reason"><label>修订原因（必填）</label><textarea id="sourceEditReason" rows="3" placeholder="说明修订依据，原始上传值将永久保留"></textarea></div></div></div>':'';
var histories=record.history.length?record.history.slice().reverse().map(function(item){return '<tr><td>V'+item.version+'</td><td>'+item.time+'</td><td>'+item.operator+'</td><td>'+item.reason+'</td><td>'+item.changes+'</td></tr>'}).join(''):'<tr><td colspan="5" style="text-align:center;color:#98a2b3">暂无修订记录</td></tr>';
var links=record.linkedCards.length?record.linkedCards.map(function(card){return '<button class="btn btn-ghost btn-xs" onclick="openLinkedReportCard(\''+card+'\')">'+card+'</button>'}).join(' '):'<span style="color:#98a2b3">尚未关联报告卡</span>';
return '<div class="page-toolbar"><div class="toolbar-actions"><button class="btn btn-ghost btn-sm" onclick="switchReportDataView(\'source\')">返回源数据列表</button>'+(record.linkedCards.length?'':'<button class="btn btn-primary btn-sm" onclick="generateReportCardFromSource(\''+record.id+'\')">生成报告卡</button>')+(reportDataState.editing?'<button class="btn btn-ghost btn-sm" onclick="reportDataState.editing=false;renderPage(\'datamgmt-source\')">取消修订</button><button class="btn btn-primary btn-sm" onclick="saveSourceRevision()">保存为新版本</button>':'<button class="btn btn-primary btn-sm" onclick="startSourceRevision(\''+record.id+'\')">修订源数据</button>')+'</div></div><div class="panel"><div class="source-detail-head"><div><div class="source-detail-title">'+record.id+' · '+record.name+'</div><div class="source-detail-meta">'+record.sourceType+' · '+record.batch+' · '+record.fileName+' 第'+record.rowNo+'行 · 上传于 '+record.uploadTime+'</div></div><div>'+sourceBadge(record.validation)+' '+sourceBadge(record.duplicate)+'</div></div><div class="source-section"><div class="source-section-title">来源与关联</div><div class="source-summary" style="margin-bottom:0"><div class="source-summary-item"><div class="source-summary-label">来源机构</div><div style="margin-top:5px;font-weight:600">'+record.org+'</div></div><div class="source-summary-item"><div class="source-summary-label">身份证号</div><div style="margin-top:5px;font-weight:600">'+record.idNo+'</div></div><div class="source-summary-item"><div class="source-summary-label">报告卡类型</div><div style="margin-top:5px">'+reportCardTypeBadge(record,detailCard)+'</div></div><div class="source-summary-item"><div class="source-summary-label">当前版本</div><div style="margin-top:5px;font-weight:600">V'+record.version+'</div></div><div class="source-summary-item"><div class="source-summary-label">关联报告卡</div><div style="margin-top:5px">'+links+'</div></div></div></div><div class="source-section"><div class="source-section-title">上传原值与当前值对比</div><table class="source-compare"><thead><tr><th>字段</th><th>上传原值（只读）</th><th>当前修正值</th><th>状态</th></tr></thead><tbody>'+compareRows+'</tbody></table></div>'+revisionForm+'<div class="source-section" style="border-bottom:0"><div class="source-section-title">修订记录</div><div class="table-wrap"><table class="data-table"><thead><tr><th>版本</th><th>修改时间</th><th>修改人</th><th>修改原因</th><th>变更内容</th></tr></thead><tbody>'+histories+'</tbody></table></div></div></div>'
}

function saveSourceRevision(){
var record=sourceDataRecords.find(function(item){return item.id===reportDataState.selectedSourceId});if(!record)return;
var next={site:document.getElementById('sourceEditSite').value.trim(),pathology:document.getElementById('sourceEditPathology').value.trim(),icd10:document.getElementById('sourceEditIcd10').value.trim()};var reason=document.getElementById('sourceEditReason').value.trim();if(!reason){toast('请填写修订原因','error');return}
var changes=[];[['发病部位','site'],['病理类型','pathology'],['ICD10','icd10']].forEach(function(field){if(record.current[field[1]]!==next[field[1]])changes.push(field[0]+'：'+record.current[field[1]]+' -> '+next[field[1]])});if(!changes.length){toast('当前没有字段变化','error');return}
record.version+=1;record.history.push({version:record.version,time:new Date().toLocaleString('zh-CN',{hour12:false}),operator:'当前用户',reason:reason,changes:changes.join('；')});record.current=next;reportDataState.editing=false;renderPage('datamgmt-source');toast('已保存为 V'+record.version+'，上传原值保持不变')
}

function openLinkedReportCard(id){reportDataState.view='cards';renderPage('datamgmt-card');setActiveMenu('datamgmt-card');cardListDetail(id)}

function linkReportCardToSource(cardId){
var card=(window.reportCardListData||[]).find(function(item){return item.id===cardId});if(!card)return;
var candidates=sourceDataRecords.filter(function(record){return record.idNo===card.idNo&&!record.linkedCards.length});
if(!candidates.length){navigateTo('datamgmt-source');toast('未找到可关联的源数据','error');return}
candidates[0].linkedCards=[cardId];renderPage('datamgmt-card');toast('已关联源数据 '+candidates[0].id);
}

function generateReportCardFromSource(id){
var record=sourceDataRecords.find(function(item){return item.id===id});if(!record)return;
var cards=window.reportCardListData||[];var existing=cards.find(function(card){return card.idNo===record.idNo});
if(existing){record.linkedCards=[existing.id];renderPage('datamgmt-source');toast('已关联既有报告卡 '+existing.id);return}
var serial=Math.max.apply(null,cards.map(function(card){return Number((card.id.match(/(\d+)$/)||['',0])[1])||0}).concat([0]))+1;var cardId='HN-2026-'+String(serial).padStart(6,'0');
cards.push({id:cardId,name:record.name,sex:'不详',birth:'',idNo:record.idNo,phone:'-',job:'-',nation:'-',marriage:'-',workUnit:'-',household:'-',residence:'-',site:record.current.site,pathology:record.current.pathology,icd10:record.current.icd10,diagnosisDate:'-',outpatientNo:'-',inpatientNo:'-',reportDate:record.uploadTime.slice(0,10),doctor:'-',reportUnit:record.org,region:'-',cardType:'<span class="badge badge-info">原始卡</span>',checkStatus:sourceBadge(record.validation),auditStatus:'<span class="badge badge-muted">未核对</span>',errors:[]});
record.linkedCards=[cardId];renderPage('datamgmt-source');toast('已由源数据生成报告卡 '+cardId);
}

var baseCardListDetail=cardListDetail;
cardListDetail=function(id){
baseCardListDetail(id);
var linked=sourceDataRecords.filter(function(record){return record.linkedCards.includes(id)});var container=document.getElementById('pageContainer');if(!container||!linked.length)return;
var rows=linked.map(function(record){return '<tr><td><a href="javascript:void(0)" onclick="openSourceDataDetail(\''+record.id+'\')">'+record.id+'</a></td><td>'+record.sourceType+'</td><td>'+record.batch+'</td><td>'+record.fileName+' / 第'+record.rowNo+'行</td><td>V'+record.version+(sourceHasChange(record)?'（已修订）':'')+'</td><td><button class="btn btn-ghost btn-xs" onclick="openSourceDataDetail(\''+record.id+'\')">查看源数据</button></td></tr>'}).join('');
container.insertAdjacentHTML('beforeend','<div class="panel" style="margin-top:16px"><div class="panel-header">数据来源 <span style="font-size:12px;color:#667085;font-weight:400;margin-left:8px">报告卡可关联一条或多条源数据</span></div><div class="panel-body"><div class="table-wrap"><table class="data-table"><thead><tr><th>源数据编号</th><th>来源</th><th>上传批次</th><th>来源文件/行号</th><th>采用版本</th><th>操作</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>')
};

var baseBiParseFile=biParseFile;
biParseFile=function(){
var before=hisRecords.map(function(row){return row.id});baseBiParseFile();var added=hisRecords.filter(function(row){return !before.includes(row.id)});added.forEach(function(row,index){sourceDataRecords.push({id:'SRC-'+String(row.id),batch:'BAT-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-01',sourceType:'批量导入',fileName:row.fileName||biState.fileName,rowNo:row.rowNo||index+1,uploadTime:row.uploadTime,org:row.reportUnit,name:row.name,idNo:row.idNo,original:{site:row.site,pathology:row.pathology,icd10:row.icd10||'-'},current:{site:row.site,pathology:row.pathology,icd10:row.icd10||'-'},validation:row.validation,duplicate:row.duplicate,linkedCards:[],version:1,history:[]})});reportDataState.view='source';renderPage('datamgmt-source');updateBreadcrumb('datamgmt-source','上报数据管理')
};

